import type { GateDef, GateType } from "./types";

function mkIn(type: GateType, label: string, outs: string[], w = 70, h = 44): GateDef {
  return { type, label, category: "Input Controls", inputs: [], outputs: outs.map(id => ({ id, label: id, side: "right" as const })), w, h };
}
function mkOut(type: GateType, label: string, ins: string[], w = 70, h = 60): GateDef {
  return { type, label, category: "Output Controls", inputs: ins.map(id => ({ id, label: id, side: "left" as const })), outputs: [], w, h };
}
function mkG(type: GateType, label: string, ins: string[], outs: {id:string;lb:string}[], w = 90, h = 52): GateDef {
  return { type, label, category: "Logic Gates", inputs: ins.map(id => ({ id, label: id.toUpperCase(), side: "left" as const })), outputs: outs.map(o => ({ id: o.id, label: o.lb, side: "right" as const })), w, h };
}
function mkC(type: GateType, label: string, ins: string[], outs: string[], w = 100, h = 72): GateDef {
  return { type, label, category: "Combinational", inputs: ins.map(id => ({ id, label: id, side: "left" as const })), outputs: outs.map(id => ({ id, label: id, side: "right" as const })), w, h };
}
function mkS(type: GateType, label: string, ins: string[], outs: string[], w = 100, h = 72): GateDef {
  return { type, label, category: "Sequential", inputs: ins.map(id => ({ id, label: id, side: "left" as const })), outputs: outs.map(id => ({ id, label: id, side: "right" as const })), w, h };
}

