const o = (n:number) => Array.from({length:n},(_,i)=>`o${i}`);
const q = (n:number) => Array.from({length:n},(_,i)=>`q${i}`);
const s = (n:number) => Array.from({length:n},(_,i)=>`s${i}`);
const p = (n:number) => Array.from({length:n},(_,i)=>`p${i}`);
const qObj = (n:number) => Array.from({length:n},(_,i)=>({id:`q${i}`,lb:`Q${i}`}));
const oObj = (n:number) => Array.from({length:n},(_,i)=>({id:`o${i}`,lb:`O${i}`}));

